INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by) VALUES ('541923bc-5233-5b79-ae5d-ea3d195d4ace', 'TUT-BAHASA16-001', 'b6666666-6666-6666-6666-666666666666', $$Bahasa Hindi: Sapaan Dasar untuk Percakapan Pertama$$, 'bahasa-hindi-sapaan-dasar', $$Panduan belajar sapaan dasar bahasa Hindi: alfabet Devanagari, pengucapan, sapaan sehari-hari, dan kesalahan umum pemula.$$, 'id', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ingin Bicara Hindi tapi Takut Salah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bahasa Hindi dipakai lebih dari 600 juta orang, tetapi banyak pemula Indonesia takut karena huruf Devanagari yang asing dan bunyi aspirasi (kh, gh, th) yang tidak ada dalam bahasa Indonesia. Kabar baiknya: Hindi memakai huruf Devanagari yang hampir selalu dibaca apa adanya, dan orang India sangat menghargai usaha orang asing berbahasa mereka.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Langkah 1: Siapkan Alat Belajar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', ARRAY[$$Aplikasi kamus Hindi-Indonesia atau Google Translate (mode suara)$$, $$Catatan kecil untuk menulis Devanagari$$, $$Video YouTube pengucapan Devanagari 10 menit sehari$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Langkah 2: Kuasai 10 Sapaan Inti$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Namaste (नमस्ते) — halo/selamat (paling aman dipakai kapan saja)$$, $$Dhanyavaad (धन्यवाद) — terima kasih$$, $$Maaf kijiye (माफ़ कीजिये) — maaf$$, $$Haan / Nahin (हाँ / नहीं) — ya / tidak$$, $$Aap kaise hain? (आप कैसे हैं?) — apa kabar? (formal)$$, $$Main theek hoon (मैं ठीक हूँ) — saya baik-baik saja$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah 3: Latih Pengucapan 15 Menit Sehari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Tirukan penutur asli dari video, rekam suara sendiri, lalu bandingkan. Fokus pada bunyi aspirasi: bedakan 'k' dan 'kh', 't' dan 'th'. Latih satu kelompok huruf Devanagari per hari, mulai dari vokal (a, aa, i, ee). Target 30 hari: bisa memesan makanan dan menawar harga dalam bahasa Hindi sederhana.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Memakai 'tu' ke orang yang baru dikenal — terkesan tidak sopan; pakai 'aap' yang formal$$, $$Mengucap 'namaste' dengan tangan di saku — sertai dengan anjali (tangan menyatu di dada)$$, $$Menghafal tanpa praktik bicara — bahasa adalah keterampilan lisan$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Uji diri: sapa diri sendiri dalam bahasa Hindi setiap pagi selama seminggu. Jika sudah bisa memperkenalkan nama, usia, dan asal tanpa melihat catatan, lanjut ke percakapan dasar.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by) VALUES ('8fb2621a-35cb-5082-90f3-0c3aa85b02cd', 'TUT-KESEHATAN32-001', 'b5555555-5555-5555-5555-555555555555', $$Kulit Gatal: Penyebab Umum dan Cara Mengatasinya$$, 'kulit-gatal-penyebab-umum', $$Panduan memahami penyebab umum kulit gatal, perawatan di rumah, dan tanda bahaya kapan harus ke dokter. Informasi umum, bukan pengganti nasihat medis.$$, 'id', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Gatal yang Mengganggu Aktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kulit gatal (pruritus) bisa muncul di satu titik atau seluruh tubuh, ringan sesekali atau terus-menerus sampai mengganggu tidur. Sebagian besar kasus ringan dan bisa diatasi di rumah, tetapi gatal yang menetap perlu diwaspadai.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Penyebab Umum Kulit Gatal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', ARRAY[$$Kulit kering — pemicu paling umum, terutama di ruangan ber-AC$$, $$Alergi — sabun, detergen, kosmetik, atau makanan tertentu$$, $$Gigitan serangga atau biang keringat$$, $$Infeksi jamur (kutu air, panu) — biasanya di area lembap$$, $$Eksim atau dermatitis — bercak merah bersisik yang kambuhan$$, $$Kondisi lain (hati, ginjal, tiroid) — biasanya gatal menyeluruh tanpa ruam jelas$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan di Rumah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Pelembap tanpa pewangi (petroleum jelly atau losion hipoalergenik)$$, $$Sabun mandi yang lembut, air hangat suam-suam kuku$$, $$Kompres dingin atau handuk basah$$, $$Pakaian katun yang longgar$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Perawatan Mandiri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Jangan digaruk — garukan memperparah iritasi dan bisa infeksi; tekan atau kompres dingin$$, $$Oleskan pelembap segera setelah mandi saat kulit masih lembap$$, $$Mandi air hangat (bukan panas) maksimal 10–15 menit$$, $$Hindari pemicu yang dicurigai: ganti sabun/detergen ke versi hipoalergenik$$, $$Jaga kuku tetap pendek agar tidak melukai kulit saat tidak sadar menggaruk$$, $$Kelola stres — stres bisa memperburuk rasa gatal$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kapan Harus ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Gatal berlangsung lebih dari 2 minggu tanpa membaik$$, $$Gatal menyeluruh tanpa ruam yang jelas$$, $$Disertai kulit menguning, penurunan berat badan, atau kelelahan berat$$, $$Ruam bernanah, bengkak, atau demam — tanda infeksi$$, $$Gatal setelah minum obat baru$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Catat pola gatal selama seminggu: kapan muncul, apa pemicunya, apa yang meredakan. Catatan ini sangat membantu dokter menegakkan diagnosis bila akhirnya perlu berobat. Artikel ini bersifat informasi umum dan bukan pengganti nasihat medis — bila ragu atau kondisi memburuk, konsultasikan ke dokter atau fasilitas kesehatan terdekat.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by) VALUES ('b8b3d2b5-c840-5061-b4c3-2d62ebdd010a', 'EXP-GEOGRAFI16-001', 'c6000001-0000-0000-0000-000000000001', $$Gunung Tertinggi di Indonesia: Dari Puncak Jaya hingga Semeru$$, 'gunung-tertinggi-di-indonesia', $$Mengenal gunung-gunung tertinggi Indonesia, dari Puncak Jaya yang bersalju abadi hingga gunung berapi aktif seperti Semeru dan Kerinci.$$, 'id', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Indonesia, Negeri Para Raksasa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Indonesia punya lebih dari 500 gunung, termasuk sekitar 130 gunung berapi aktif. Gunung tertinggi di Indonesia bukanlah gunung berapi, melainkan Puncak Jaya di Papua yang puncaknya diselimuti salju abadi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Puncak Jaya: Atap Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Puncak Jaya (4.884 mdpl) di Pegunungan Sudirman, Papua, adalah gunung tertinggi di Indonesia sekaligus titik tertinggi Oseania dan bagian dari Seven Summits dunia. Gletser tropis di puncaknya kini menyusut akibat pemanasan global.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Gunung Berapi Tertinggi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Gunung Kerinci (3.805 mdpl, Sumatera) — gunung berapi tertinggi di Indonesia$$, $$Gunung Rinjani (3.726 mdpl, Lombok) — kaldera Segara Anak yang memesona$$, $$Gunung Semeru (3.676 mdpl, Jawa) — tertinggi di Pulau Jawa, meletus berkala$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Mengapa Banyak Gunung Tinggi di Indonesia?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Indonesia berada di pertemuan tiga lempeng tektonik: Indo-Australia, Eurasia, dan Pasifik. Tumbukan lempeng mengangkat pegunungan lipatan (seperti di Papua) sekaligus membentuk busur gunung berapi dari Sumatera hingga Nusa Tenggara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Mendaki dengan Aman dan Bertanggung Jawab$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Cek status aktivitas gunung berapi di situs resmi PVMBG sebelum berangkat$$, $$Siapkan fisik, pakaian hangat, dan logistik minimal 2–3 hari$$, $$Gunakan jasa pemandu lokal berlisensi$$, $$Bawa kembali semua sampah — gunung adalah warisan alam yang harus dijaga$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by) VALUES ('826b9069-c858-5e1c-9651-627322f0df06', 'EXP-TEKNOLOGI18-001', 'c7777777-7777-7777-7777-777777777777', $$Teknologi Wearable: Dari Jam Pintar hingga Pelacak Kesehatan$$, 'teknologi-wearable-jam-pintar', $$Mengenal teknologi wearable: cara kerja jam pintar, manfaat pelacakan kesehatan, dan hal yang perlu diperhatikan soal privasi data.$$, 'id', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Komputer yang Dipakai di Tubuh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Teknologi wearable adalah perangkat elektronik yang dikenakan di tubuh: jam pintar, gelang kebugaran, earbud pintar, hingga cincin pintar. Perangkat ini memadukan sensor, konektivitas, dan aplikasi dalam ukuran mini.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Cara Kerja Jam Pintar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Jam pintar memakai sensor optik untuk membaca detak jantung dari aliran darah di pergelangan, akselerometer untuk gerak dan langkah, serta GPS untuk jarak. Data diolah di perangkat lalu disinkronkan ke aplikasi ponsel.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Apa yang Bisa Dilacak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Detak jantung sepanjang hari dan kualitas tidur$$, $$Kadar oksigen darah (SpO2) pada model tertentu$$, $$Jumlah langkah, kalori, dan zona latihan$$, $$Deteksi jatuh dan panggilan darurat otomatis$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Manfaat dan Keterbatasan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Wearable membantu orang lebih sadar akan aktivitas dan pola tidur, bahkan kadang mendeteksi kelainan irama jantung lebih dini. Namun ia alat bantu gaya hidup, bukan alat diagnosis medis — akurasinya kalah dari alat klinis, dan data kesehatan tersimpan di server perusahaan sehingga kebijakan privasinya perlu dibaca.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Masa Depan Wearable$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Tren berikutnya: sensor non-invasif untuk gula darah, kain pintar, dan kecerdasan buatan yang memberi saran kesehatan personal. Perangkat akan makin kecil, akurat, dan hemat daya.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by) VALUES ('35c29e11-9948-57c3-a1bc-8609453ad1f0', 'SCH-SMP-MAT11-001', 'd4444444-4444-4444-4444-444444444444', $$Matematika Kelas 9: Bangun Ruang Sisi Lengkung$$, 'matematika-kelas-9-bangun-ruang', $$Materi bangun ruang sisi lengkung kelas 9: tabung, kerucut, bola — unsur, luas permukaan, volume, contoh soal, latihan, dan kunci jawaban.$$, 'id', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu mengidentifikasi unsur-unsur tabung, kerucut, dan bola, serta menghitung luas permukaan dan volumenya dengan tepat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Tabung$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', ARRAY[$$Unsur: 2 lingkaran (alas dan tutup), 1 selimut persegi panjang$$, $$Luas permukaan = 2 × π × r × (r + t)$$, $$Volume = π × r² × t$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Kerucut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Unsur: 1 lingkaran alas, 1 titik puncak, garis pelukis s = √(r² + t²)$$, $$Luas permukaan = π × r × (r + s)$$, $$Volume = 1/3 × π × r² × t$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Bola$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Unsur: jari-jari r, diameter 2r; tidak punya rusuk dan titik sudut$$, $$Luas permukaan = 4 × π × r²$$, $$Volume = 4/3 × π × r³$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Soal Terpecahkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Tabung berjari-jari 7 cm dan tinggi 10 cm. Hitung volumenya! (π = 22/7). Jawab: V = π × r² × t = 22/7 × 7 × 7 × 10 = 1.540 cm³. Pilih π = 22/7 bila jari-jari kelipatan 7, π = 3,14 untuk yang lain.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$1. Tabung r = 10 cm, t = 15 cm. Hitung volume! (π = 3,14)$$, $$2. Kerucut r = 6 cm, t = 8 cm. Hitung luas permukaan! (π = 3,14)$$, $$3. Bola r = 21 cm. Hitung volume! (π = 22/7)$$, $$Kunci: 1) 4.710 cm³; 2) s = 10 cm, L = 301,44 cm²; 3) 38.808 cm³$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by) VALUES ('cf0a4a2e-f0e7-59ca-906d-cb51df545f40', 'SCH-SD-BIN13-001', 'd3333333-3333-3333-3333-333333333333', $$Bahasa Indonesia Kelas 4: Menulis Karangan Sederhana$$, 'bahasa-indonesia-kelas-4-karangan', $$Materi menulis karangan sederhana kelas 4: pengertian, struktur karangan, langkah menulis, contoh karangan, latihan, dan kunci jawaban.$$, 'id', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu diharapkan mampu menjelaskan pengertian karangan, menyebutkan strukturnya, dan menulis karangan sederhana dengan ejaan yang benar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Karangan?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Karangan adalah rangkaian kalimat yang disusun menjadi paragraf untuk menyampaikan gagasan. Karangan yang baik punya satu ide pokok yang jelas dan kalimat-kalimat pendukung yang nyambung.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Struktur Karangan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Pembuka — kalimat yang menarik perhatian pembaca$$, $$Isi — penjelasan atau cerita tentang topik$$, $$Penutup — kesimpulan atau pesan dari karangan$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Menulis Karangan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Tentukan topik, misalnya 'Liburanku', lalu buat kerangka 3–4 poin$$, $$Kembangkan setiap poin menjadi satu paragraf$$, $$Periksa ejaan: huruf kapital di awal kalimat dan nama orang, titik di akhir kalimat$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Karangan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Liburanku. Liburan kemarin aku pergi ke rumah nenek di desa. Di sana aku bermain di sawah dan menangkap ikan di sungai. Nenek memasakkan sayur lodeh kesukaanku. Aku senang sekali dan ingin kembali lagi tahun depan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$1. Apa yang dimaksud dengan karangan?$$, $$2. Sebutkan 3 bagian struktur karangan!$$, $$3. Tulis kerangka karangan bertopik 'Hewan Kesayanganku'!$$, $$4. Tulis satu karangan sederhana 3 paragraf tentang 'Sekolahku'!$$, $$Kunci: 1) rangkaian kalimat/paragraf yang menyampaikan gagasan runtut; 2) pembuka, isi, penutup; 3) contoh: pembuka — kucingku bernama Moli, isi — ciri dan kebiasaannya, penutup — aku sayang Moli; 4) dinilai dari 3 paragraf, ejaan benar, ide runtut$$]::text[]));
